CREATE OR REPLACE FUNCTION public.closed_operation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='completed' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Operación cerrada definitivamente'; END IF; IF NEW.status='completed' AND OLD.status<>'completed' AND (NOT NEW.buyer_confirmed OR NOT NEW.seller_confirmed OR NEW.payment_stage<>'completion_pending' OR EXISTS(SELECT 1 FROM public.disputes d WHERE d.transaction_id=NEW.id AND d.status='open')) THEN RAISE EXCEPTION 'Faltan confirmaciones o existe una disputa'; END IF; RETURN NEW; END $$;
CREATE TRIGGER closed_operation_guard BEFORE UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.closed_operation_guard();
CREATE OR REPLACE FUNCTION public.closed_message_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE state_value text; BEGIN SELECT status INTO state_value FROM public.transactions WHERE id=NEW.transaction_id FOR UPDATE; IF state_value NOT IN ('pending','disputed') OR state_value IS NULL THEN RAISE EXCEPTION 'La conversación está cerrada: solo lectura'; END IF; RETURN NEW; END $$;
CREATE TRIGGER closed_message_guard BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.closed_message_guard();
ALTER TABLE public.auctions ADD COLUMN delivery_snapshot jsonb;
ALTER TABLE public.auction_payment_acceptances ADD COLUMN delivery_snapshot jsonb;
CREATE OR REPLACE FUNCTION public.delivery_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE mode_value text; BEGIN IF TG_OP='UPDATE' AND OLD.status<>'draft' AND NEW.delivery_snapshot IS DISTINCT FROM OLD.delivery_snapshot THEN RAISE EXCEPTION 'Las condiciones de entrega publicadas no pueden cambiar'; END IF; IF NEW.delivery_snapshot IS NOT NULL THEN mode_value:=NEW.delivery_snapshot->>'mode'; IF mode_value IS NULL OR mode_value NOT IN ('free','paid','pickup','other') OR jsonb_typeof(NEW.delivery_snapshot)<>'object' OR length(coalesce(NEW.delivery_snapshot->>'conditions',''))>2000 THEN RAISE EXCEPTION 'Entrega no válida'; END IF; IF mode_value='paid' AND (NEW.delivery_snapshot->>'cost' IS NULL OR (NEW.delivery_snapshot->>'cost')::numeric<=0) THEN RAISE EXCEPTION 'Indica el costo adicional'; END IF; IF mode_value<>'paid' AND NEW.delivery_snapshot->>'cost' IS NOT NULL THEN RAISE EXCEPTION 'Costo adicional no permitido para esta modalidad'; END IF; IF mode_value='other' AND length(trim(coalesce(NEW.delivery_snapshot->>'conditions','')))<5 THEN RAISE EXCEPTION 'Describe la modalidad de entrega'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER delivery_guard BEFORE INSERT OR UPDATE ON public.auctions FOR EACH ROW EXECUTE FUNCTION public.delivery_guard();
CREATE TABLE public.service_requests(auction_id uuid PRIMARY KEY REFERENCES public.auctions(id),request jsonb NOT NULL,locations_verified boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.service_requests TO authenticated;
GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.service_details_allowed(_auction uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.auctions a JOIN public.profiles p ON p.id=auth.uid() WHERE a.id=_auction AND a.auction_type='service' AND (a.seller_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (p.account_status='active' AND a.status IN ('active','scheduled','ended_unsold','ended_sold') AND public.has_role(auth.uid(),'seller') AND public.has_active_seller_sub(auth.uid())))) $$;
REVOKE ALL ON FUNCTION public.service_details_allowed(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.service_details_allowed(uuid) TO authenticated;
CREATE POLICY service_requests_read ON public.service_requests FOR SELECT TO authenticated USING(public.service_details_allowed(auction_id));
CREATE OR REPLACE FUNCTION public.get_service_request(_auction uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result_value jsonb; BEGIN IF NOT public.service_details_allowed(_auction) THEN RAISE EXCEPTION 'Detalles privados disponibles solo para cliente y proveedores elegibles'; END IF; SELECT request||jsonb_build_object('locations_verified',locations_verified) INTO result_value FROM public.service_requests WHERE auction_id=_auction; RETURN result_value; END $$;
REVOKE ALL ON FUNCTION public.get_service_request(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_service_request(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.service_required_fields(_category text) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _category WHEN 'transport' THEN ARRAY['origin','origin_reference','destination','destination_reference','datetime','cargo','dimensions','access','contact'] WHEN 'mechanics' THEN ARRAY['brand','model','year','vehicle','problem','attendance','deadline'] WHEN 'plumbing' THEN ARRAY['problem_type','location','urgency','problem','visit','deadline'] WHEN 'electrical' THEN ARRAY['problem_type','location','urgency','problem','voltage','visit','deadline'] WHEN 'accounting' THEN ARRAY['specialty','scope','deliverables','mode','deadline','requirements','jurisdiction','period','volume'] WHEN 'professional' THEN ARRAY['specialty','scope','deliverables','mode','deadline','requirements'] WHEN 'home' THEN ARRAY['location','area','tasks','frequency','supplies','deadline'] WHEN 'construction' THEN ARRAY['location','work','measurements','materials','deadline'] WHEN 'technology' THEN ARRAY['system','problem','deliverables','mode','deadline'] WHEN 'design' THEN ARRAY['brief','formats','references','revisions','deadline'] WHEN 'events' THEN ARRAY['event','location','datetime','guests','equipment'] WHEN 'tourism' THEN ARRAY['destination','date','travelers','language','accessibility'] WHEN 'agriculture' THEN ARRAY['location','crop','area','work','deadline'] WHEN 'pets' THEN ARRAY['animal','care','location','datetime','behavior'] WHEN 'health' THEN ARRAY['service','qualification','mode','deadline','requirements'] WHEN 'business' THEN ARRAY['sector','scope','deliverables','team','deadline'] WHEN 'other' THEN ARRAY['custom_category','scope','deliverables','mode','deadline'] ELSE NULL END $$;
CREATE OR REPLACE FUNCTION public.service_request_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE required_key text; required_keys text[]; value_row record; BEGIN required_keys:=public.service_required_fields(NEW.request->>'category'); IF required_keys IS NULL OR jsonb_typeof(NEW.request->'values')<>'object' OR length(trim(coalesce(NEW.request->>'subcategory','')))=0 OR length(NEW.request::text)>30000 THEN RAISE EXCEPTION 'Solicitud no válida'; END IF; FOREACH required_key IN ARRAY required_keys LOOP IF length(trim(coalesce(NEW.request->'values'->>required_key,'')))=0 THEN RAISE EXCEPTION 'Completa los campos de la solicitud'; END IF; END LOOP; FOR value_row IN SELECT v.key,v.value FROM jsonb_each(NEW.request->'values') v(key,value) LOOP IF jsonb_typeof(value_row.value)<>'string' OR length(value_row.value#>>'{}')>2000 THEN RAISE EXCEPTION 'Campo no válido'; END IF; END LOOP; IF NEW.request->'values'->>'mode'='Presencial' AND length(trim(coalesce(NEW.request->'values'->>'location','')))=0 THEN RAISE EXCEPTION 'Indica ubicación presencial'; END IF; IF NEW.request->'values'->>'attendance'='Asistencia en carretera' AND (length(trim(coalesce(NEW.request->'values'->>'road_location','')))=0 OR length(trim(coalesce(NEW.request->'values'->>'road_contact','')))=0) THEN RAISE EXCEPTION 'Indica ubicación y contacto de asistencia'; END IF; IF NEW.request->'values'->>'attendance'='Visita al lugar' AND length(trim(coalesce(NEW.request->'values'->>'location','')))=0 THEN RAISE EXCEPTION 'Indica ubicación de visita'; END IF; NEW.locations_verified:=false; RETURN NEW; END $$;
CREATE TRIGGER service_request_guard BEFORE INSERT OR UPDATE OF request ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.service_request_guard();
CREATE OR REPLACE FUNCTION public.save_extended_draft(_data jsonb,_private jsonb,_delivery jsonb,_request jsonb,_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE draft_id uuid; BEGIN IF _data->>'auction_type'='item' AND _delivery IS NULL THEN RAISE EXCEPTION 'Elige modalidad de entrega'; END IF; IF _data->>'auction_type'='service' AND _request IS NULL THEN RAISE EXCEPTION 'Completa la solicitud de servicio'; END IF; draft_id:=public.save_auction_draft(_id,_data||jsonb_build_object('service_from',NULL,'service_to',NULL),_private); IF _data->>'auction_type'='item' THEN UPDATE public.auctions SET delivery_snapshot=_delivery,delivery_terms=coalesce(_delivery->>'conditions','') WHERE id=draft_id; ELSE INSERT INTO public.service_requests(auction_id,request) VALUES(draft_id,_request) ON CONFLICT(auction_id) DO UPDATE SET request=excluded.request,updated_at=now(); END IF; RETURN draft_id; END $$;
REVOKE ALL ON FUNCTION public.save_extended_draft(jsonb,jsonb,jsonb,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_extended_draft(jsonb,jsonb,jsonb,jsonb,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.extended_publish_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.status='draft' AND NEW.status IN ('active','scheduled') THEN IF NEW.auction_type='item' AND NEW.delivery_snapshot IS NULL AND length(trim(coalesce(NEW.delivery_terms,'')))=0 THEN RAISE EXCEPTION 'Indica modalidad y condiciones de entrega'; END IF; IF NEW.auction_type='service' THEN IF NOT EXISTS(SELECT 1 FROM public.service_requests r WHERE r.auction_id=NEW.id) THEN RAISE EXCEPTION 'Completa el formulario específico del servicio'; END IF; IF EXISTS(SELECT 1 FROM public.service_requests r WHERE r.auction_id=NEW.id AND r.request->>'category'='transport' AND NOT r.locations_verified) THEN RAISE EXCEPTION 'Transporte requiere validar ambas ubicaciones con el servicio de mapas configurado'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER extended_publish_guard BEFORE UPDATE ON public.auctions FOR EACH ROW EXECUTE FUNCTION public.extended_publish_guard();
CREATE OR REPLACE FUNCTION public.bid_with_delivery_acceptance(_auction uuid,_amount numeric,_key text,_accept boolean,_terms jsonb,_delivery jsonb,_conditions text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE auction_row public.auctions; result_value jsonb; BEGIN SELECT * INTO auction_row FROM public.auctions WHERE id=_auction FOR UPDATE; IF auction_row.id IS NULL THEN RAISE EXCEPTION 'Subasta no disponible'; END IF; IF auction_row.auction_type='item' AND auction_row.delivery_snapshot IS NOT NULL AND (_accept IS DISTINCT FROM true OR _delivery IS DISTINCT FROM auction_row.delivery_snapshot) THEN RAISE EXCEPTION 'Acepta las condiciones actuales de entrega'; END IF; IF auction_row.auction_type='service' AND EXISTS(SELECT 1 FROM public.service_requests r WHERE r.auction_id=_auction) AND NOT public.service_details_allowed(_auction) THEN RAISE EXCEPTION 'No tienes acceso a los detalles necesarios para ofertar'; END IF; result_value:=public.bid_with_payment_acceptance(_auction,_amount,_key,_accept,_terms,_conditions); UPDATE public.auction_payment_acceptances SET delivery_snapshot=auction_row.delivery_snapshot WHERE bid_id=(result_value->>'bid_id')::uuid AND delivery_snapshot IS NULL; RETURN result_value; END $$;
REVOKE ALL ON FUNCTION public.bid_with_delivery_acceptance(uuid,numeric,text,boolean,jsonb,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bid_with_delivery_acceptance(uuid,numeric,text,boolean,jsonb,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.bid_delivery_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.auctions a WHERE a.id=NEW.auction_id AND a.auction_type='item' AND a.delivery_snapshot IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.auction_payment_acceptances x WHERE x.bid_id=NEW.id AND x.user_id=NEW.bidder_id AND x.delivery_snapshot=a.delivery_snapshot)) THEN RAISE EXCEPTION 'Debes aceptar las condiciones de entrega'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER bid_delivery_guard AFTER INSERT ON public.bids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.bid_delivery_guard();
GRANT SELECT(delivery_snapshot) ON public.auctions TO anon,authenticated;
CREATE OR REPLACE VIEW public.auctions_safe WITH (security_barrier=true) AS SELECT a.id,a.seller_id,a.title,a.description,a.category_id,a.country,a.city,a.scope,a.delivery_terms,CASE WHEN a.auction_type='service' THEN ARRAY[]::text[] ELSE a.images END AS images,CASE WHEN a.auction_type='item' THEN a.starting_price ELSE NULL END AS starting_price,a.min_increment,a.currency,a.status,a.duration_hours,a.starts_at,a.ends_at,a.original_ends_at,a.current_price,a.bid_count,a.leader_id,a.winner_id,a.has_reserve,a.reserve_met,a.extensions_count,a.flagged,a.created_at,a.updated_at,a.auction_type,NULL::text AS service_from,NULL::text AS service_to,a.duration_minutes,a.selection_pending,a.accepted_payment_methods,a.delivery_snapshot FROM public.auctions a WHERE a.status<>'draft' OR a.seller_id=auth.uid() OR public.is_staff(auth.uid());
REVOKE SELECT(service_from,service_to) ON public.auctions FROM anon,authenticated;
COMMENT ON COLUMN public.auctions.service_from IS 'DEPRECATED: private origin is stored in service_requests';
COMMENT ON COLUMN public.auctions.service_to IS 'DEPRECATED: private destination is stored in service_requests';